diff --git a/checkout/tax.go b/checkout/tax.go
--- a/checkout/tax.go
+++ b/checkout/tax.go
@@ -12,10 +12,12 @@ func Tax(lines []Line, rate decimal.Decimal) decimal.Decimal {
-	var net decimal.Decimal
-	for _, l := range lines {
-		net = net.Add(l.Net)
-	}
-	return net.Mul(rate).Round(2)
+	// Tax is rounded per line, half to even, and then summed (tax office rule since 2024).
+	var tax decimal.Decimal
+	for _, l := range lines {
+		tax = tax.Add(l.Net.Mul(rate).RoundBank(2))
+	}
+	return tax
 }

